/* EasyBILL operations workspace: suppliers, purchasing, returns, shifts, audit, loyalty, imports and offline queue. */
const Operations = {
  currentTab: 'overview',
  collections: ['suppliers','purchases','returns','shifts','audit','loyalty','offline_outbox'],
  id() { return (globalThis.crypto?.randomUUID?.() || `eb-${Date.now()}-${Math.random().toString(16).slice(2)}`); },
  all(key) { return Storage.getAll(key); },
  money(n) { return Utils.formatCurrency(Number(n) || 0); },
  esc(s) { return Utils.escapeHtml(String(s ?? '')); },
  audit(action, targetType, targetId, reason = '', details = {}) {
    const rows = this.all('audit');
    const event = { id: this.id(), action, targetType, targetId: String(targetId || ''), reason, details, userId: Cloud.user?.id || 'local-user', role: Cloud.role || 'local-owner', createdAt: new Date().toISOString() };
    rows.unshift(event); Storage.replaceLocal('audit', rows.slice(0, 5000));
    if (Cloud.user && Cloud.client && Cloud.businessId) Cloud.client.from('audit_logs').insert({business_id:Cloud.businessId,actor_id:Cloud.user.id,actor_role:Cloud.role,action,target_type:targetType,target_id:String(targetId||''),reason:reason||null,details:details||{}}).then(({error})=>{if(error)console.warn('Cloud audit log could not be written:',error.message);});
  },
  requireManager() {
    if (Cloud.user && !['owner','manager'].includes(Cloud.role)) { Utils.toast('This action requires owner or manager permission.', 'error'); return false; }
    return true;
  },
  render() {
    if (Cloud.user && !['owner','manager','cashier'].includes(Cloud.role)) { Utils.toast('No active business membership was found.','error'); return; }
    const root = document.getElementById('page-content'); if (!root) return;
    const tabs = (Cloud.user && Cloud.role === 'cashier') ? [['overview','Overview'],['returns','Returns'],['shifts','Cashier shifts'],['loyalty','Loyalty']] : [['overview','Overview'],['suppliers','Suppliers'],['purchases','Purchases'],['returns','Returns'],['shifts','Cashier shifts'],['loyalty','Loyalty'],...(Cloud.user? [['staff','Staff access']] : []),['data','Import / Export'],['audit','Audit log']];
    root.innerHTML = `<section class="ops-workspace"><div class="ops-notice"><strong>${Cloud.user ? 'Cloud account active' : 'Local mode'}</strong><span>${Cloud.user ? 'Existing cloud billing remains cloud-backed. This workspace records operational workflows locally until the included database migration is applied and its sync integration is configured.' : 'Operational records are saved on this device. Export regular backups before changing devices.'}</span></div><div class="ops-tabs">${tabs.map(([id,label])=>`<button class="btn ${this.currentTab===id?'btn-primary':'btn-secondary'}" onclick="Operations.show('${id}')">${label}</button>`).join('')}</div><div id="ops-panel"></div></section>`;
    const notice = root.querySelector('.ops-notice span');
    if (notice && Cloud.user) notice.textContent = 'Supplier, purchase, return, shift, and loyalty actions use your cloud business. Device-only offline records are listed in the outbox.';
    this.show(this.currentTab);
    if (Cloud.user) this.hydrateCloud().then(()=>this.show(this.currentTab)).catch(error=>console.warn('Operations data refresh failed:',error.message));
  },
  async hydrateCloud() {
    const manager=['owner','manager'].includes(Cloud.role);
    const {data: loyaltySettings,error: loyaltySettingsError}=await Cloud.client.from('loyalty_settings').select('*').eq('business_id',Cloud.businessId).maybeSingle();if(loyaltySettingsError)throw loyaltySettingsError;if(loyaltySettings)Storage.set('loyaltySettings',{earnRate:Number(loyaltySettings.earn_points_per_100),pointValue:Number(loyaltySettings.currency_per_point),minimumRedemptionPoints:Number(loyaltySettings.minimum_redemption_points)});
    const requests=[];
    if(manager) requests.push(['suppliers',Cloud.client.from('suppliers').select('*').eq('business_id',Cloud.businessId).order('created_at',{ascending:false})]);
    if(manager) requests.push(['purchases',Cloud.client.from('purchases').select('*,purchase_items(*)').eq('business_id',Cloud.businessId).order('created_at',{ascending:false})]);
    requests.push(['returns',Cloud.client.from('returns').select('*,return_items(*),invoices(invoice_number)').eq('business_id',Cloud.businessId).order('created_at',{ascending:false})]);
    requests.push(['shifts',Cloud.client.from('cashier_shifts').select('*').eq('business_id',Cloud.businessId).order('opened_at',{ascending:false})]);
    requests.push(['cashMovements',Cloud.client.from('cash_movements').select('*').eq('business_id',Cloud.businessId).order('created_at',{ascending:false})]);
    requests.push(['loyalty',Cloud.client.from('loyalty_ledger').select('*,customers(name)').eq('business_id',Cloud.businessId).order('created_at',{ascending:false})]);
    if(manager) requests.push(['staff',Cloud.client.from('business_members').select('user_id,role,is_active,created_at,profiles(name,email)').eq('business_id',Cloud.businessId).order('created_at',{ascending:false})]);
    if(manager) requests.push(['audit',Cloud.client.from('audit_logs').select('*').eq('business_id',Cloud.businessId).order('created_at',{ascending:false}).limit(500)]);
    for(const [key,promise] of requests){const {data,error}=await promise;if(error)throw error;const local=this.all(key).filter(r=>!r.cloudSynced);let mapped=(data||[]).map(r=>{if(key==='suppliers')return{id:r.id,name:r.name,phone:r.phone||'',email:r.email||'',gstin:r.gstin||'',address:r.address||'',createdAt:r.created_at,cloudSynced:true};if(key==='purchases'){const item=r.purchase_items?.[0]||{};return{id:r.id,supplierId:r.supplier_id||'',supplierName:this.all('suppliers').find(s=>s.id===r.supplier_id)?.name||'Supplier',productId:item.product_id||'',productName:item.product_name||'Purchase',quantity:item.received_quantity||item.quantity||0,unitCost:item.unit_cost||0,reference:r.supplier_invoice_ref||'',createdAt:r.created_at,status:r.status,cloudSynced:true};}if(key==='returns'){const item=r.return_items?.[0]||{};return{id:r.id,invoiceNumber:r.invoices?.invoice_number||r.invoice_id,productName:item.product_name||'Returned item',quantity:item.quantity||0,amount:r.refund_amount,method:r.refund_method||'',disposition:r.stock_disposition,reason:r.reason,status:r.status,createdAt:r.created_at,cloudSynced:true};}if(key==='shifts')return{id:r.id,terminal:r.terminal_id,cashier:r.cashier_id,openingCash:Number(r.opening_cash),closingCash:r.closing_cash==null?'':Number(r.closing_cash),expectedCash:r.expected_cash==null?'':Number(r.expected_cash),difference:r.difference==null?'':Number(r.difference),status:r.status,openedAt:r.opened_at,closedAt:r.closed_at,notes:r.closing_note||'',userId:r.cashier_id,cloudSynced:true};if(key==='cashMovements')return{id:r.id,shiftId:r.shift_id,direction:r.direction,amount:Number(r.amount),reason:r.reason,createdAt:r.created_at,createdBy:r.created_by,cloudSynced:true};if(key==='loyalty')return{id:r.id,customerId:r.customer_id,customerName:r.customers?.name||'Customer',points:r.points,reason:r.reason,createdAt:r.created_at,userId:r.created_by,cloudSynced:true};if(key==='staff')return{id:r.user_id,userId:r.user_id,role:r.role,is_active:r.is_active,name:r.profiles?.name||'',email:r.profiles?.email||'',createdAt:r.created_at,cloudSynced:true};return{id:r.id,action:r.action,targetType:r.target_type,targetId:r.target_id,reason:r.reason,details:r.details,userId:r.actor_id,role:r.actor_role,createdAt:r.created_at,cloudSynced:true};});Storage.replaceLocal(key,[...local,...mapped]);}
  },
  show(tab) { if (Cloud.user && Cloud.role === 'cashier' && !['overview','returns','shifts','loyalty'].includes(tab)) { Utils.toast('Billing accounts can access cashier operations only.','error'); tab='overview'; } this.currentTab = tab; const panel = document.getElementById('ops-panel'); if (!panel) return; const data = this.all(tab === 'data' || tab === 'overview' ? 'offline_outbox' : tab); let html = '';
    if (tab === 'overview') {
      const pending = this.all('offline_outbox').filter(x=>x.status!=='synced').length;
      html = `<div class="ops-grid"><article class="ops-card"><small>Suppliers</small><strong>${this.all('suppliers').length}</strong></article><article class="ops-card"><small>Purchase entries</small><strong>${this.all('purchases').length}</strong></article><article class="ops-card"><small>Returns recorded</small><strong>${this.all('returns').length}</strong></article><article class="ops-card"><small>Pending offline records</small><strong>${pending}</strong></article></div><div class="ops-card"><h3>Operational workspace</h3><p>Record supplier details, stock purchases, returns, shift cash reconciliation and customer loyalty activity. Every local workflow adds an audit entry. Cloud deployment requires the included additive SQL migration plus server-side policies; migration is not automatically applied.</p><div class="ops-actions"><button class="btn btn-primary" onclick="Operations.show('purchases')">Record purchase</button><button class="btn btn-secondary" onclick="Operations.show('returns')">Record return</button><button class="btn btn-secondary" onclick="Operations.show('shifts')">Open / close shift</button></div></div><div class="ops-card"><h3>Offline outbox</h3><p>${pending} pending item(s). Local entries are preserved across refresh/restart; cloud synchronization for operational records remains pending configuration.</p>${this.table(this.all('offline_outbox'),['kind','status','createdAt','message'])}</div>`;
    } else if (tab === 'suppliers') {
      html = `<div class="ops-card"><h3>Add supplier</h3><form class="ops-form" onsubmit="Operations.addSupplier(event)"><label>Name<input name="name" required maxlength="120"></label><label>Phone<input name="phone" maxlength="40"></label><label>Email<input name="email" type="email" maxlength="160"></label><label>GSTIN / Business ID<input name="gstin" maxlength="30"></label><label>Address<input name="address" maxlength="300"></label><button class="btn btn-primary">Save supplier</button></form></div><div class="ops-card"><h3>Suppliers (${this.all('suppliers').length})</h3>${this.table(this.all('suppliers'),['name','phone','email','gstin','createdAt'])}<div class="ops-actions">${this.all('suppliers').map(s=>`<button class="btn btn-secondary" onclick="Operations.editSupplier('${this.esc(s.id)}')">Edit ${this.esc(s.name)}</button><button class="btn btn-secondary" onclick="Operations.deleteSupplier('${this.esc(s.id)}')">Delete ${this.esc(s.name)}</button>`).join('')}</div></div>`;
    } else if (tab === 'purchases') {
      const products=this.all('products');
      html = `<div class="ops-card"><h3>Receive stock purchase</h3><p>Purchase receipt records a stock movement locally, or uses the atomic migration-backed RPC for cloud businesses.</p><form class="ops-form" onsubmit="Operations.addPurchase(event)"><label>Supplier<select name="supplierId"><option value="">Unspecified supplier</option>${this.all('suppliers').map(s=>`<option value="${this.esc(s.id)}">${this.esc(s.name)}</option>`).join('')}</select></label><label>Product<select name="productId" required>${products.map(p=>`<option value="${this.esc(p.id)}">${this.esc(p.name)} — stock ${Number(p.stock)||0}</option>`).join('')}</select></label><label>Quantity<input name="quantity" type="number" min="0.001" step="0.001" required></label><label>Unit cost<input name="unitCost" type="number" min="0" step="0.01" required></label><label>Supplier invoice reference<input name="reference" maxlength="100"></label><label>Batch / lot number<input name="batchNumber" maxlength="80"></label><label>Expiry date<input name="expiryDate" type="date"></label><button class="btn btn-primary" ${products.length?'':'disabled'}>Receive purchase</button></form></div><div class="ops-card"><h3>Purchase history</h3>${this.table(this.all('purchases'),['supplierName','productName','quantity','unitCost','reference','createdAt'])}</div>`;
    } else if (tab === 'returns') {
      html = `<div class="ops-card"><h3>Record return / refund</h3><p>Creates a traceable return request. It does not delete or rewrite the original invoice. UPI/card refunds are not sent by EasyBILL; confirm completion only after the payment provider confirms it.</p><form class="ops-form" onsubmit="Operations.addReturn(event)"><label>Invoice number<input name="invoiceNumber" required maxlength="80"></label><label>Product name<input name="productName" required maxlength="160"></label><label>Quantity<input name="quantity" type="number" min="0.001" step="0.001" required></label><label>Refund amount<input name="amount" type="number" min="0" step="0.01" required></label><label>Refund method<select name="method"><option>Cash</option><option>UPI (manual confirmation required)</option><option>Card (manual confirmation required)</option><option>Store credit</option></select></label><label>Disposition<select name="disposition"><option value="resalable">Resalable</option><option value="damaged">Damaged / non-resalable</option></select></label><label>Reason<textarea name="reason" required maxlength="500"></textarea></label><button class="btn btn-primary">Record return</button></form></div><div class="ops-card"><h3>Return history</h3><div class="ops-table-wrap"><table class="ops-table"><thead><tr>${['invoiceNumber','productName','quantity','amount','method','status','reason','createdAt','Actions'].map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${this.all('returns').slice(0,500).map(r=>`<tr><td>${this.esc(r.invoiceNumber)}</td><td>${this.esc(r.productName)}</td><td>${this.esc(r.quantity)}</td><td>${this.esc(r.amount)}</td><td>${this.esc(r.method)}</td><td>${this.esc(r.status)}</td><td>${this.esc(r.reason)}</td><td>${this.esc(r.createdAt)}</td><td>${(['owner','manager'].includes(Cloud.role)||!Cloud.user)?`${['requested','recorded-not-refunded'].includes(r.status)?`<button class="btn btn-secondary" onclick="Operations.approveReturn('${this.esc(r.id)}')">Approve</button>`:''}${['approved','refund_pending'].includes(r.status)?`<button class="btn btn-primary" onclick="Operations.confirmReturnRefund('${this.esc(r.id)}')">Confirm refund done</button>`:''}`:'Manager approval required'}</td></tr>`).join('')}</tbody></table></div></div>`;
    } else if (tab === 'shifts') {
      const open=this.all('shifts').find(s=>s.status==='open');
      html = `<div class="ops-card"><h3>${open?'Close active shift':'Open cashier shift'}</h3>${open?`<p>Shift opened ${this.esc(open.openedAt)} with ${this.money(open.openingCash)} opening cash.</p><form class="ops-form" onsubmit="Operations.recordCashMovement(event)"><label>Movement<select name="direction"><option value="in">Cash paid in</option><option value="out">Cash paid out</option></select></label><label>Amount<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Reason<input name="reason" maxlength="300" required></label><button class="btn btn-secondary">Record cash movement</button></form><form class="ops-form" onsubmit="Operations.closeShift(event)"><label>Actual closing cash<input name="closingCash" type="number" min="0" step="0.01" required></label><label>Closing notes<textarea name="notes" maxlength="500"></textarea></label><button class="btn btn-primary">Close shift</button></form>`:`<form class="ops-form" onsubmit="Operations.openShift(event)"><label>Terminal name<input name="terminal" maxlength="80" value="Counter 1" required></label><label>Opening cash<input name="openingCash" type="number" min="0" step="0.01" required></label><button class="btn btn-primary">Open shift</button></form>`}</div><div class="ops-card"><h3>Shift history</h3>${this.table(this.all('shifts'),['terminal','cashier','openingCash','closingCash','expectedCash','difference','status','openedAt','closedAt'])}</div>`;
    } else if (tab === 'loyalty') {
      html = `${['owner','manager'].includes(Cloud.role)||!Cloud.user?`<div class="ops-card"><h3>Loyalty settings</h3><form class="ops-form" onsubmit="Operations.saveLoyaltySettings(event)"><label>Points earned per ₹100 eligible spend<input name="earnRate" type="number" min="0" max="100" step="0.1" value="${Number(Storage.get('loyaltySettings')?.earnRate ?? 1)}" required></label><label>Rupee value per point<input name="pointValue" type="number" min="0" max="100" step="0.01" value="${Number(Storage.get('loyaltySettings')?.pointValue ?? 0.5)}" required></label><label>Minimum points to redeem<input name="minimumRedemptionPoints" type="number" min="0" max="100000" step="1" value="${Number(Storage.get('loyaltySettings')?.minimumRedemptionPoints ?? 10)}" required></label><button class="btn btn-primary">Save rules</button></form></div><div class="ops-card"><h3>Manual points adjustment (manager only)</h3><form class="ops-form" onsubmit="Operations.adjustPoints(event)"><label>Customer<select name="customerId" required>${this.all('customers').map(c=>`<option value="${this.esc(c.id)}">${this.esc(c.name)} ${this.esc(c.phone||'')}</option>`).join('')}</select></label><label>Points (+/-)<input name="points" type="number" step="1" min="-100000" max="100000" required></label><label>Reason<input name="reason" required maxlength="300"></label><button class="btn btn-primary" ${this.all('customers').length?'':'disabled'}>Record points entry</button></form></div>`:`<div class="ops-card"><h3>Customer loyalty ledger</h3><p>Cashier adjustments are disabled; apply loyalty redemptions through an authorized billing workflow.</p></div>`}<div class="ops-card"><h3>Points ledger</h3>${this.table(this.all('loyalty'),['customerName','points','reason','createdAt'])}</div>`;
    } else if (tab === 'staff') {
      html = `<div class="ops-card"><h3>Invite staff member</h3><form class="ops-form" onsubmit="Operations.inviteStaff(event)"><label>Staff email<input name="email" type="email" required maxlength="254"></label><label>Role<select name="role"><option value="cashier">Cashier</option>${Cloud.role==='owner'?'<option value="manager">Manager</option>':''}</select></label><button class="btn btn-primary">Send invitation</button></form></div><div class="ops-card"><h3>Business memberships</h3><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Created</th><th>Action</th></tr></thead><tbody>${this.all('staff').map(r=>`<tr><td>${this.esc(r.name)}</td><td>${this.esc(r.email)}</td><td>${this.esc(r.role)}</td><td>${r.is_active?'Active':'Inactive'}</td><td>${this.esc(r.createdAt)}</td><td>${r.userId!==Cloud.user?.id&&(Cloud.role==='owner'||r.role==='cashier')?`<button class="btn btn-secondary" onclick="Operations.setStaffActive('${this.esc(r.userId)}',${!r.is_active})">${r.is_active?'Deactivate':'Reactivate'}</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`;
    } else if (tab === 'data') {
      html = `<div class="ops-card"><h3>CSV import / export</h3><p>Product CSV import validates the entire file before writing. Existing products are matched by ID, then barcode; omitted rows are never deleted. Use backups before bulk changes.</p><div class="ops-actions"><button class="btn btn-primary" onclick="Operations.downloadTemplate()">Download product template</button><button class="btn btn-secondary" onclick="Operations.exportProducts()">Export products CSV</button><button class="btn btn-secondary" onclick="Operations.exportReport()">Export sales summary CSV</button><button class="btn btn-secondary" onclick="Operations.exportReportPDF()">Export sales summary PDF</button><button class="btn btn-secondary" onclick="Operations.exportBackup()">Export local backup JSON</button><label class="btn btn-secondary">Validate product CSV<input type="file" accept=".csv,text/csv" onchange="Operations.importProducts(event)" hidden></label></div><p id="ops-import-status" role="status"></p><div id="ops-import-preview"></div></div><div class="ops-card"><h3>Offline outbox</h3>${this.table(this.all('offline_outbox'),['id','kind','status','createdAt','message'])}<button class="btn btn-secondary" onclick="Operations.retryOutbox()">Retry pending (local validation)</button></div>`;
    } else if (tab === 'audit') {
      html = `<div class="ops-card"><h3>Audit events (${this.all('audit').length})</h3><p>Local audit records are append-only through this interface. Local storage is not tamper-proof; cloud audit protection is defined in the migration.</p>${this.table(this.all('audit').slice(0,250),['createdAt','userId','role','action','targetType','targetId','reason'])}<button class="btn btn-secondary" onclick="Operations.exportAudit()">Export audit CSV</button></div>`;
    }
    if (tab === 'loyalty') html = this.renderLoyaltySummary() + html;
    panel.innerHTML = html; Icons.renderAll();
  },
  renderLoyaltySummary() {
    const balances = new Map();
    const customerNames = new Map(this.all('customers').map(customer => [customer.id, customer.name]));
    const ledger = this.all('loyalty');
    let earned = 0;
    let used = 0;
    ledger.forEach(entry => {
      const points = Number(entry.points) || 0;
      if (points > 0) earned += points;
      if (points < 0) used += Math.abs(points);
      const current = balances.get(entry.customerId) || {
        name: entry.customerName || customerNames.get(entry.customerId) || 'Customer',
        points: 0,
        entries: 0
      };
      current.points += points;
      current.entries += 1;
      balances.set(entry.customerId, current);
    });
    const ranked = [...balances.entries()]
      .map(([customerId, balance]) => ({ customerId, ...balance, points: Math.max(0, balance.points) }))
      .filter(balance => balance.points > 0)
      .sort((a, b) => b.points - a.points)
      .slice(0, 10);
    const customersWithBalance = [...balances.values()].filter(balance => balance.points > 0).length;
    const outstanding = [...balances.values()].reduce((sum, balance) => sum + Math.max(0, balance.points), 0);
    const balanceRows = ranked.length
      ? `<div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>Customer</th><th>Points available</th><th>Ledger entries</th></tr></thead><tbody>${ranked.map(row => `<tr><td>${this.esc(row.name)}</td><td>${row.points}</td><td>${row.entries}</td></tr>`).join('')}</tbody></table></div>`
      : '<p class="ops-empty">No customers have a points balance yet.</p>';
    return `<div class="ops-grid"><article class="ops-card"><small>Points outstanding</small><strong>${outstanding}</strong></article><article class="ops-card"><small>Customers with balance</small><strong>${customersWithBalance}</strong></article><article class="ops-card"><small>Points earned</small><strong>${earned}</strong></article><article class="ops-card"><small>Points redeemed / adjusted</small><strong>${used}</strong></article></div><div class="ops-card"><div class="ops-actions" style="justify-content:space-between;align-items:center"><h3>Top customer balances</h3><button class="btn btn-secondary" type="button" onclick="Operations.exportLoyalty()">Export ledger</button></div>${balanceRows}</div>`;
  },
  table(rows, cols) { if(!rows.length) return '<p class="ops-empty">No records yet.</p>'; return `<div class="ops-table-wrap"><table class="ops-table"><thead><tr>${cols.map(c=>`<th>${this.esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,500).map(r=>`<tr>${cols.map(c=>`<td>${this.esc(r[c] ?? '')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`; },
  recordLocalLoyaltyRedemption(invoice){if(Cloud.user||!invoice?.customerId||Number(invoice.loyaltyPointsRedeemed)<=0)return;const customer=Storage.getById('customers',invoice.customerId),rows=this.all('loyalty');rows.unshift({id:this.id(),customerId:invoice.customerId,customerName:customer?.name||invoice.customerName||'Customer',invoiceId:invoice.id,points:-Number(invoice.loyaltyPointsRedeemed),reason:'Points redeemed at checkout',createdAt:new Date().toISOString(),userId:'local-user'});Storage.replaceLocal('loyalty',rows);this.audit('loyalty.redeem','invoice',invoice.id,'Points redeemed',{points:invoice.loyaltyPointsRedeemed});},
  async inviteStaff(e){e.preventDefault();if(!this.requireManager())return;const f=e.currentTarget,email=f.email.value.trim().toLowerCase(),role=f.role.value;if(Cloud.role==='manager'&&role!=='cashier'){Utils.toast('Managers can invite cashiers only.','error');return;}try{const {data,error}=await Cloud.client.functions.invoke('invite-staff',{body:{business_id:Cloud.businessId,email,role}});if(error){let message=error.message;try{const response=error.context;if(response&&typeof response.json==='function'){const details=await response.json();message=details?.error||details?.message||message;}}catch{}throw new Error(message);}if(data?.error)throw new Error(data.error);Utils.toast(data?.message||'Invitation sent.','success');this.audit('staff.invite','business_member',email,`Invited as ${role}`);await this.hydrateCloud();this.show('staff');}catch(err){Utils.toast(`Staff invitation failed: ${err.message}`,'error');}},
  async setStaffActive(userId,active){if(!this.requireManager()||userId===Cloud.user?.id)return;const member=this.all('staff').find(r=>r.userId===userId);if(!member)return;if(Cloud.role==='manager'&&member.role!=='cashier'){Utils.toast('Managers can only deactivate/reactivate cashier accounts.','error');return;}if(!confirm(`${active?'Reactivate':'Deactivate'} this staff membership?`))return;const {error}=await Cloud.client.from('business_members').update({is_active:active}).eq('business_id',Cloud.businessId).eq('user_id',userId);if(error){Utils.toast(`Membership update failed: ${error.message}`,'error');return;}member.is_active=active;Storage.replaceLocal('staff',this.all('staff'));this.audit(active?'staff.reactivate':'staff.deactivate','business_member',userId,'Membership status changed');this.show('staff');},
  awardLocalLoyalty(invoice){if(Cloud.user||!invoice?.customerId||!['paid','complete'].includes(String(invoice.status).toLowerCase()))return;const settings=Storage.get('loyaltySettings')||{earnRate:1,pointValue:0.5};const eligibleSpend=Math.max(0,(Number(invoice.grandTotal)||0)-(Number(invoice.loyaltyPointsRedeemed)||0)*Number(settings.pointValue||0.5));const points=Math.floor(eligibleSpend/100*(Number(settings.earnRate)||0));if(points<=0)return;const customer=Storage.getById('customers',invoice.customerId),rows=this.all('loyalty');rows.unshift({id:this.id(),customerId:invoice.customerId,customerName:customer?.name||invoice.customerName||'Customer',invoiceId:invoice.id,points,reason:'Points earned on completed sale',createdAt:new Date().toISOString(),userId:'local-user'});Storage.replaceLocal('loyalty',rows);this.audit('loyalty.earn','invoice',invoice.id,'Points earned',{points});},
  async addSupplier(e) { e.preventDefault(); if(!this.requireManager())return; const f=e.currentTarget; const name=f.name.value.trim(); if(!name)return; let row={id:this.id(),name,phone:f.phone.value.trim(),email:f.email.value.trim(),gstin:f.gstin.value.trim().toUpperCase(),address:f.address.value.trim(),createdAt:new Date().toISOString()}; const rows=this.all('suppliers'); if(rows.some(s=>s.name.toLowerCase()===name.toLowerCase() && s.phone===row.phone)){Utils.toast('A supplier with the same name and phone already exists.','warning');return;} if(Cloud.user){try{const {data,error}=await Cloud.client.from('suppliers').insert({business_id:Cloud.businessId,name:row.name,phone:row.phone||null,email:row.email||null,gstin:row.gstin||null,address:row.address||null,created_by:Cloud.user.id}).select().single();if(error)throw error;row={...row,id:data.id,cloudSynced:true};}catch(err){Utils.toast(`Supplier was not saved to cloud: ${err.message}`,'error');return;}} rows.unshift(row); Storage.replaceLocal('suppliers',rows);this.audit('supplier.create','supplier',row.id,'Created supplier');Utils.toast(Cloud.user?'Supplier saved to cloud.':'Supplier saved locally.','success');this.show('suppliers'); },
  async editSupplier(id){if(!this.requireManager())return;const rows=this.all('suppliers'),row=rows.find(s=>s.id===id);if(!row)return;const name=prompt('Supplier name',row.name);if(name===null)return;if(!name.trim()){Utils.toast('Supplier name is required.','error');return;}const phone=prompt('Supplier phone',row.phone||'');if(phone===null)return;const email=prompt('Supplier email',row.email||'');if(email===null)return;const gstin=prompt('GSTIN / business ID',row.gstin||'');if(gstin===null)return;const address=prompt('Supplier address',row.address||'');if(address===null)return;if(Cloud.user){const {error}=await Cloud.client.from('suppliers').update({name:name.trim(),phone:phone.trim()||null,email:email.trim()||null,gstin:gstin.trim()||null,address:address.trim()||null}).eq('id',id).eq('business_id',Cloud.businessId);if(error){Utils.toast(`Supplier update failed: ${error.message}`,'error');return;}}Object.assign(row,{name:name.trim(),phone:phone.trim(),email:email.trim(),gstin:gstin.trim(),address:address.trim()});Storage.replaceLocal('suppliers',rows);this.audit('supplier.update','supplier',id,'Updated supplier');this.show('suppliers');},
  async deleteSupplier(id){if(!this.requireManager()||!confirm('Delete this supplier record? Existing purchase history will remain.'))return;const rows=this.all('suppliers'),row=rows.find(s=>s.id===id);if(!row)return;if(Cloud.user){const {error}=await Cloud.client.from('suppliers').delete().eq('id',id).eq('business_id',Cloud.businessId);if(error){Utils.toast(`Supplier delete failed: ${error.message}`,'error');return;}}Storage.replaceLocal('suppliers',rows.filter(s=>s.id!==id));this.audit('supplier.delete','supplier',id,'Deleted supplier');this.show('suppliers');},
  async addPurchase(e) { e.preventDefault(); if(!this.requireManager())return; const f=e.currentTarget; const p=Storage.getById('products',f.productId.value); const qty=Number(f.quantity.value), cost=Number(f.unitCost.value); if(!p||!Number.isFinite(qty)||qty<=0||!Number.isFinite(cost)||cost<0){Utils.toast('Check product, quantity and cost.','error');return;} const supplier=this.all('suppliers').find(s=>s.id===f.supplierId.value); let row={id:this.id(),supplierId:supplier?.id||'',supplierName:supplier?.name||'Unspecified',productId:p.id,productName:p.name,quantity:qty,unitCost:cost,reference:f.reference.value.trim(),batchNumber:f.batchNumber.value.trim(),expiryDate:f.expiryDate.value||'',createdAt:new Date().toISOString(),status:'received'}; const old=Number(p.stock)||0; if(Cloud.user){try{const {data,error}=await Cloud.client.rpc('receive_purchase',{p_business_id:Cloud.businessId,p_supplier_id:supplier?.cloudSynced?supplier.id:null,p_product_id:p.id,p_quantity:qty,p_unit_cost:cost,p_reference:row.reference||null,p_expiry_date:row.expiryDate||null,p_batch_number:row.batchNumber||null});if(error)throw error;row.id=data;row.cloudSynced=true;await Cloud.refreshBusinessProducts();}catch(err){Utils.toast(`Purchase was not received in cloud: ${err.message}`,'error');return;}}else if(EasyBillDomain.isStockTracked(p)){Storage.update('products',p.id,{stock:old+qty,costPrice:cost,purchasePrice:cost,...(row.expiryDate?{expiryDate:row.expiryDate}:{})}); const moves=this.all('stockMovements');moves.unshift({id:this.id(),productId:p.id,type:'purchase',quantity:qty,before:old,after:old+qty,reference:row.reference||row.id,reason:'Supplier purchase received',createdAt:row.createdAt});Storage.replaceLocal('stockMovements',moves);} const purchases=this.all('purchases');purchases.unshift(row);Storage.replaceLocal('purchases',purchases);this.audit('purchase.receive','purchase',row.id,'Received stock',{productId:p.id,quantity:qty,unitCost:cost});if(!Cloud.user)Storage.set('offline_outbox',[...this.all('offline_outbox'),{id:this.id(),kind:'purchase',status:'local-only',createdAt:row.createdAt,message:'Local purchase record'}]);Utils.toast(Cloud.user?'Purchase received in cloud and stock updated.':'Purchase recorded and local stock updated.','success');this.show('purchases'); },
  async addReturn(e) { e.preventDefault(); const f=e.currentTarget; const qty=Number(f.quantity.value), amount=Number(f.amount.value);if(!Number.isFinite(qty)||qty<=0||!Number.isFinite(amount)||amount<0||!f.reason.value.trim()){Utils.toast('Enter a valid quantity, amount and reason.','error');return;} const inv=this.all('invoices').find(i=>String(i.invoiceNumber)===f.invoiceNumber.value.trim()); if(!inv){Utils.toast('Original invoice was not found in the current invoice list.','error');return;}if(!['paid','complete'].includes(String(inv.status).toLowerCase())){Utils.toast('Only completed sales can be returned.','error');return;} if(inv){const item=(inv.items||[]).find(i=>(i.name||'').toLowerCase()===f.productName.value.trim().toLowerCase()); if(!item){Utils.toast('That product was not found on the selected invoice.','error');return;} const already=this.all('returns').filter(r=>r.invoiceNumber===inv.invoiceNumber&&r.productName.toLowerCase()===item.name.toLowerCase()).reduce((s,r)=>s+Number(r.quantity),0);const returnCheck=EasyBillDomain.validateReturnQuantity(item.quantity,already,qty);if(!returnCheck.valid){Utils.toast(returnCheck.message,'error');return;}const maxRefund=Number(item.amount||0)/Math.max(Number(item.quantity)||1,1)*qty;if(amount>maxRefund+0.01){Utils.toast(`Refund amount cannot exceed ${maxRefund.toFixed(2)} for the selected quantity.`,'error');return;}} let row={id:this.id(),invoiceId:inv.id,invoiceNumber:f.invoiceNumber.value.trim(),productId:(inv.items||[]).find(i=>(i.name||'').toLowerCase()===f.productName.value.trim().toLowerCase())?.productId||'',productName:f.productName.value.trim(),quantity:qty,amount,method:f.method.value,disposition:f.disposition.value,reason:f.reason.value.trim(),status:'recorded-not-refunded',createdAt:new Date().toISOString(),userId:Cloud.user?.id||'local-user'}; if(Cloud.user){try{if(!inv)throw new Error('Original invoice must be available in this device cache to match the item safely.');const item=(inv.items||[]).find(i=>(i.name||'').toLowerCase()===row.productName.toLowerCase());if(!item?.id)throw new Error('Invoice item identifier is missing; refresh invoices and retry.');const {data,error}=await Cloud.client.rpc('request_invoice_return',{p_business_id:Cloud.businessId,p_invoice_id:inv.id,p_invoice_item_id:item.id,p_quantity:qty,p_refund_amount:amount,p_reason:row.reason,p_disposition:row.disposition,p_refund_method:row.method.toLowerCase().includes('upi')?'upi':row.method.toLowerCase().includes('card')?'card':row.method.toLowerCase().includes('cash')?'cash':'other'});if(error)throw error;row.id=data;row.status='requested';row.cloudSynced=true;}catch(err){Utils.toast(`Return was not submitted to cloud: ${err.message}`,'error');return;}} const rows=this.all('returns');rows.unshift(row);Storage.replaceLocal('returns',rows);this.audit('return.record','return',row.id,row.reason,{invoiceNumber:row.invoiceNumber,quantity:qty,amount});if(!Cloud.user)Storage.set('offline_outbox',[...this.all('offline_outbox'),{id:this.id(),kind:'return',status:'local-only',createdAt:row.createdAt,message:'Refund is recorded only; no external payment executed'}]);Utils.toast('Return recorded. Refund is not marked as paid.','success');this.show('returns'); },
  async approveReturn(id) { if(!this.requireManager())return;const rows=this.all('returns'),row=rows.find(r=>r.id===id);if(!row)return;if(Cloud.user){try{const {data,error}=await Cloud.client.rpc('approve_invoice_return',{p_business_id:Cloud.businessId,p_return_id:id,p_refund_confirmed:false});if(error)throw error;row.status=data.status;row.cloudSynced=true;await Cloud.refreshBusinessProducts();}catch(err){Utils.toast(`Return approval failed: ${err.message}`,'error');return;}}else{if(row.disposition==='resalable'&&row.productId){const p=Storage.getById('products',row.productId);if(p&&EasyBillDomain.isStockTracked(p)){Storage.update('products',p.id,{stock:(Number(p.stock)||0)+Number(row.quantity)});const moves=this.all('stockMovements');moves.unshift({id:this.id(),productId:p.id,type:'return',quantity:Number(row.quantity),reason:`Approved return ${row.invoiceNumber}`,createdAt:new Date().toISOString()});Storage.replaceLocal('stockMovements',moves);}}const inv=this.all('invoices').find(i=>i.id===row.invoiceId);if(inv?.customerId&&Number(inv.grandTotal)>0){const earned=this.all('loyalty').filter(l=>l.invoiceId===inv.id&&l.points>0).reduce((sum,l)=>sum+Number(l.points),0);const reverse=Math.min(earned,Math.floor(earned*Number(row.amount)/Number(inv.grandTotal)));if(reverse>0){const ledger=this.all('loyalty');ledger.unshift({id:this.id(),customerId:inv.customerId,customerName:inv.customerName,invoiceId:inv.id,points:-reverse,reason:`Points reversed for return ${row.invoiceNumber}`,createdAt:new Date().toISOString()});Storage.replaceLocal('loyalty',ledger);}}row.status='approved';}Storage.replaceLocal('returns',rows);this.audit('return.approve','return',id,'Manager approved return');Utils.toast('Return approved. Refund is not yet marked completed.','success');this.show('returns');},
  async confirmReturnRefund(id) { if(!this.requireManager())return;if(!confirm('Confirm that the refund has actually been completed outside EasyBILL?'))return;const rows=this.all('returns'),row=rows.find(r=>r.id===id);if(!row)return;if(Cloud.user){try{const {data,error}=await Cloud.client.rpc('approve_invoice_return',{p_business_id:Cloud.businessId,p_return_id:id,p_refund_confirmed:true});if(error)throw error;row.status=data.status;row.cloudSynced=true;}catch(err){Utils.toast(`Refund confirmation failed: ${err.message}`,'error');return;}}else row.status='refunded';Storage.replaceLocal('returns',rows);this.audit('return.refund_confirmed','return',id,'Operator confirmed refund completion');Utils.toast('Refund marked completed based on your confirmation.','success');this.show('returns');},
  async openShift(e) { e.preventDefault();if(this.all('shifts').some(s=>s.status==='open')){Utils.toast('A shift is already open on this device.','warning');return;} const f=e.currentTarget, amount=Number(f.openingCash.value);if(!Number.isFinite(amount)||amount<0)return;let row={id:this.id(),terminal:f.terminal.value.trim(),cashier:Cloud.user?.email||'Local cashier',userId:Cloud.user?.id||'local-user',openingCash:amount,status:'open',openedAt:new Date().toISOString()};if(Cloud.user){try{const {data,error}=await Cloud.client.from('cashier_shifts').insert({business_id:Cloud.businessId,cashier_id:Cloud.user.id,terminal_id:row.terminal,opening_cash:amount,opening_note:null}).select().single();if(error)throw error;row={...row,id:data.id,openedAt:data.opened_at,cloudSynced:true};}catch(err){Utils.toast(`Shift could not be opened in cloud: ${err.message}`,'error');return;}}const rows=this.all('shifts');rows.unshift(row);Storage.replaceLocal('shifts',rows);this.audit('shift.open','shift',row.id,'Shift opened');this.show('shifts'); },
  async recordCashMovement(e){e.preventDefault();const f=e.currentTarget,shift=this.all('shifts').find(s=>s.status==='open'),amount=Number(f.amount.value),reason=f.reason.value.trim();if(!shift||!Number.isFinite(amount)||amount<=0||!reason){Utils.toast('Open a shift and enter a valid amount/reason.','error');return;}let row={id:this.id(),shiftId:shift.id,direction:f.direction.value,amount,reason,createdAt:new Date().toISOString(),createdBy:Cloud.user?.id||'local-user'};if(Cloud.user){const {data,error}=await Cloud.client.from('cash_movements').insert({business_id:Cloud.businessId,shift_id:shift.id,direction:row.direction,amount,reason,created_by:Cloud.user.id}).select().single();if(error){Utils.toast(`Cash movement was not saved: ${error.message}`,'error');return;}row={...row,id:data.id,cloudSynced:true};}const rows=this.all('cashMovements');rows.unshift(row);Storage.replaceLocal('cashMovements',rows);this.audit('shift.cash_movement','shift',shift.id,reason,{direction:row.direction,amount});Utils.toast('Cash movement recorded.','success');this.show('shifts');},
  async closeShift(e) { e.preventDefault();const f=e.currentTarget, rows=this.all('shifts'), row=rows.find(s=>s.status==='open');if(!row)return;const actual=Number(f.closingCash.value);if(!Number.isFinite(actual)||actual<0)return;const opened=new Date(row.openedAt);const sales=this.all('invoices').filter(i=>new Date(i.createdAt||i.invoiceDate||0)>=opened&&['paid','complete'].includes(String(i.status).toLowerCase()));const cash=sales.reduce((sum,i)=>sum+(Array.isArray(i.payments)&&i.payments.length?i.payments.filter(p=>String(p.method).toLowerCase()==='cash').reduce((sub,p)=>sub+Number(p.amount||0),0):(String(i.paymentMethod||'').toLowerCase()==='cash'?Number(i.grandTotal||i.total||0):0)),0);const movements=this.all('cashMovements').filter(m=>m.shiftId===row.id);const cashIn=movements.filter(m=>m.direction==='in').reduce((sum,m)=>sum+Number(m.amount||0),0),cashOut=movements.filter(m=>m.direction==='out').reduce((sum,m)=>sum+Number(m.amount||0),0);row.expectedCash=Number((Number(row.openingCash)+cash+cashIn-cashOut).toFixed(2));row.closingCash=actual;row.difference=Number((actual-row.expectedCash).toFixed(2));row.status='closed';row.closedAt=new Date().toISOString();row.notes=f.notes.value.trim();if(Cloud.user){try{const {data,error}=await Cloud.client.rpc('close_cashier_shift',{p_business_id:Cloud.businessId,p_shift_id:row.id,p_actual_cash:actual,p_closing_note:row.notes});if(error)throw error;row.expectedCash=Number(data.expected_cash);row.difference=Number(data.difference);row.status=data.status;row.closedAt=data.closed_at;}catch(err){Utils.toast(`Shift close was not saved to cloud: ${err.message}`,'error');return;}}Storage.replaceLocal('shifts',rows);this.audit('shift.close','shift',row.id,'Shift closed',{expectedCash:row.expectedCash,actualCash:actual,difference:row.difference});this.show('shifts'); },
  async saveLoyaltySettings(e){e.preventDefault();if(!this.requireManager())return;const f=e.currentTarget;const earn=Number(f.earnRate.value),value=Number(f.pointValue.value),minimum=Number(f.minimumRedemptionPoints.value);if(earn<0||earn>100||value<0||value>100||!Number.isInteger(minimum)||minimum<0||minimum>100000)return;if(Cloud.user){const {error}=await Cloud.client.from('loyalty_settings').upsert({business_id:Cloud.businessId,earn_points_per_100:earn,currency_per_point:value,minimum_redemption_points:minimum,updated_by:Cloud.user.id},{onConflict:'business_id'});if(error){Utils.toast(`Loyalty settings were not saved: ${error.message}`,'error');return;}}Storage.set('loyaltySettings',{earnRate:earn,pointValue:value,minimumRedemptionPoints:minimum,updatedAt:new Date().toISOString()});this.audit('loyalty.settings','settings','loyalty','Updated loyalty settings');Utils.toast(Cloud.user?'Loyalty settings saved to cloud.':'Loyalty settings saved locally.','success');},
  async adjustPoints(e){e.preventDefault();const f=e.currentTarget,c=Storage.getById('customers',f.customerId.value),points=Number(f.points.value),reason=f.reason.value.trim();if(!c||!Number.isInteger(points)||!reason)return;let row={id:this.id(),customerId:c.id,customerName:c.name,points,reason,createdAt:new Date().toISOString(),userId:Cloud.user?.id||'local-user'};if(Cloud.user){const {data,error}=await Cloud.client.rpc('adjust_loyalty_points',{p_business_id:Cloud.businessId,p_customer_id:c.id,p_points:points,p_reason:reason});if(error){Utils.toast(`Loyalty adjustment was not saved: ${error.message}`,'error');return;}row={...row,id:data,cloudSynced:true};}const rows=this.all('loyalty');rows.unshift(row);Storage.replaceLocal('loyalty',rows);this.audit('loyalty.adjust','customer',c.id,reason,{points});this.show('loyalty');},
  csv(rows, columns) { const q=v=>{let s=String(v??'');if(/^[\s]*[=+@]/.test(s)||/^[\s]*-(?=[=+@\s])/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};return [columns.map(q).join(','),...rows.map(r=>columns.map(c=>q(r[c])).join(','))].join('\r\n'); },
  download(name,content,type='text/csv;charset=utf-8') { const blob=new Blob(['\ufeff',content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000); },
  exportProducts(){const rows=this.all('products').map(p=>({id:p.id,name:p.name,barcode:p.barcode||'',sku:p.sku||'',price:p.price,purchasePrice:p.purchasePrice??p.costPrice??'',gstRate:p.gstRate||0,stock:p.stock||0,unit:p.unit||'Pcs',trackStock:!!p.trackStock}));this.download('easybill-products.csv',this.csv(rows,['id','name','barcode','sku','price','purchasePrice','gstRate','stock','unit','trackStock']));},
  exportReport(){const rows=this.all('invoices').map(i=>({invoiceNumber:i.invoiceNumber,date:i.invoiceDate,total:i.grandTotal??i.total??0,status:i.status,paymentMethod:i.paymentMethod}));this.download('easybill-sales-summary.csv',this.csv(rows,['invoiceNumber','date','total','status','paymentMethod']));},
  exportReportPDF(){const JsPDF=window.jspdf?.jsPDF;if(!JsPDF){Utils.toast('PDF library is unavailable. Check the app connection and try again.','error');return;}const doc=new JsPDF();const invoices=this.all('invoices');const revenue=invoices.filter(i=>['paid','complete'].includes(String(i.status).toLowerCase())).reduce((sum,i)=>sum+Number(i.grandTotal??i.total??0),0);doc.setFontSize(18);doc.text('EasyBILL Sales Summary',14,18);doc.setFontSize(10);doc.text(`Generated ${new Date().toLocaleString()}`,14,25);doc.text(`Invoices: ${invoices.length}`,14,33);doc.text(`Paid sales total: ${this.money(revenue)}`,14,40);let y=50;doc.text('Invoice',14,y);doc.text('Date',70,y);doc.text('Total',112,y);doc.text('Status',155,y);y+=7;for(const i of invoices){if(y>275){doc.addPage();y=18;}doc.text(String(i.invoiceNumber||'').slice(0,25),14,y);doc.text(String(i.invoiceDate||''),70,y);doc.text(this.money(i.grandTotal??i.total??0),112,y);doc.text(String(i.status||''),155,y);y+=6;}doc.save('easybill-sales-summary.pdf');},

  exportLoyalty(){const rows=this.all('loyalty').map(entry=>({customer:entry.customerName||this.all('customers').find(customer=>customer.id===entry.customerId)?.name||'Customer',points:Number(entry.points)||0,reason:entry.reason||'',date:entry.createdAt||''}));this.download('easybill-loyalty-ledger.csv',this.csv(rows,['customer','points','reason','date']));},
  exportAudit(){this.download('easybill-audit.csv',this.csv(this.all('audit'),['createdAt','userId','role','action','targetType','targetId','reason']));},
  downloadTemplate(){this.download('easybill-product-template.csv','name,barcode,sku,price,purchasePrice,gstRate,stock,unit,trackStock\r\nExample Product,8901234567890,SKU-001,100,70,5,10,Pcs,true');},
  exportBackup(){const payload={version:'1.0',exportedAt:new Date().toISOString(),customers:this.all('customers'),products:this.all('products'),invoices:this.all('invoices'),settings:Storage.get('settings')||{},...Object.fromEntries(this.collections.map(k=>[k,this.all(k)]))};this.download('easybill-local-backup.json',JSON.stringify(payload,null,2),'application/json;charset=utf-8');},
  parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){cell+='"';i++;}else if(c==='"')quoted=false;else cell+=c;}else if(c==='"')quoted=true;else if(c===','){row.push(cell);cell='';}else if(c==='\n'){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('CSV has an unclosed quoted field.');if(cell.length||row.length){row.push(cell.replace(/\r$/,''));rows.push(row);}return rows.filter(r=>r.some(v=>v.trim()!==''));},
  async importProducts(e){const file=e.target.files?.[0];if(!file)return;const status=document.getElementById('ops-import-status');try{if(file.size>10*1024*1024)throw Error('CSV must be 10 MB or smaller.');const parsed=this.parseCSV(await file.text());if(parsed.length<2)throw Error('CSV must contain a header and at least one row.');const headers=parsed.shift().map(h=>h.trim());const required=['name','price'];if(required.some(h=>!headers.includes(h)))throw Error('Required columns: name, price. Download the sample template.');const candidates=parsed.map((values,index)=>{const r=Object.fromEntries(headers.map((h,i)=>[h,values[i]??'']));const price=Number(r.price),gst=Number(r.gstRate||0),stock=Number(r.stock||0);const errors=[];if(!r.name.trim())errors.push('name required');if(!Number.isFinite(price)||price<0)errors.push('price invalid');if(!Number.isFinite(gst)||gst<0||gst>100)errors.push('GST must be 0–100');if(!Number.isFinite(stock)||stock<0)errors.push('stock invalid');if(r.barcode&&parsed.some((other,j)=>j!==index&&headers.includes('barcode')&&other[headers.indexOf('barcode')]===r.barcode))errors.push('duplicate barcode in file');return {row:r,errors,line:index+2};});const bad=candidates.filter(c=>c.errors.length);document.getElementById('ops-import-preview').innerHTML=`<p>${candidates.length} rows checked; ${bad.length} invalid. ${bad.length?'Nothing has been imported. Fix errors and retry.':'All rows valid. Confirm to apply updates/additions.'}</p>${this.table(bad.map(b=>({line:b.line,errors:b.errors.join('; '),name:b.row.name})),['line','name','errors'])}${bad.length?'':`<button class="btn btn-primary" onclick="Operations.commitImport()">Confirm import ${candidates.length} rows</button>`}`;this._pendingImport=bad.length?null:candidates;status.textContent=bad.length?'Import blocked by validation errors.':'Validation passed; no changes made yet.';}catch(err){status.textContent=err.message;this._pendingImport=null;}e.target.value='';},
  async commitImport(){if(!this.requireManager()||!this._pendingImport)return;const rows=this.all('products');const candidates=this._pendingImport;const mapped=candidates.map(c=>{const r=c.row;const old=rows.find(p=>(r.id&&p.id===r.id)||(r.barcode&&p.barcode===r.barcode));return {old,r,values:{name:r.name.trim(),barcode:r.barcode||'',sku:r.sku||'',price:Number(r.price),purchasePrice:Number(r.purchasePrice||0),gstRate:Number(r.gstRate||0),stock:Number(r.stock||0),unit:r.unit||'Pcs',trackStock:String(r.trackStock||'true').toLowerCase()!=='false'}};});if(Cloud.user){try{const payload=mapped.map(({old,r,values})=>({id:old?.id||null,name:values.name,barcode:values.barcode||null,hsn_sac:null,unit:values.unit,unit_price:values.price,purchase_price:values.purchasePrice,gst_rate:values.gstRate,current_stock:values.stock,low_stock_threshold:old?.lowStockThreshold||5,track_stock:values.trackStock,description:old?.description||null,image_url:old?.image||null,manufacturing_date:old?.manufacturingDate||null,expiry_date:old?.expiryDate||null}));const {error}=await Cloud.client.rpc('bulk_import_products',{p_business_id:Cloud.businessId,p_rows:payload});if(error)throw error;await Cloud.refreshBusinessProducts();}catch(err){Utils.toast(`Import was not committed to cloud: ${err.message}`,'error');return;}}else{for(const {old,values} of mapped){if(old)Object.assign(old,values);else rows.push({id:this.id(),...values});}Storage.replaceLocal('products',rows);}this.audit('products.import','products','bulk',`Imported ${candidates.length} product rows`);if(!Cloud.user)Storage.set('offline_outbox',[...this.all('offline_outbox'),{id:this.id(),kind:'product-import',status:'local-only',createdAt:new Date().toISOString(),message:`${candidates.length} products imported locally`}]);this._pendingImport=null;Utils.toast(Cloud.user?'Product import committed to cloud.':'Products imported locally.','success');this.show('data');},
  async syncPendingInvoices() {
    if (!Cloud.user || !Cloud.client || !Cloud.businessId || !navigator.onLine) return;
    const rows = this.all('offline_outbox'); let changed = false;
    for (const row of rows) {
      if (row.kind !== 'invoice' || row.status === 'synced' || !row.invoice) continue;
      try {
        const invoice = { ...row.invoice, status: 'paid', clientTransactionId: row.id };
        const saved = await Cloud.saveInvoice(invoice, invoice.id);
        if (!saved) throw new Error('Server did not return the saved invoice.');
        row.status = 'synced'; row.message = 'Server-confirmed'; row.syncedAt = new Date().toISOString();
        const localInvoices = this.all('invoices'); const ix = localInvoices.findIndex(i=>i.id===invoice.id);
        if (ix >= 0) localInvoices[ix] = { ...saved, syncStatus: 'synced' }; else localInvoices.unshift({ ...saved, syncStatus: 'synced' });
        Storage.replaceLocal('invoices', localInvoices); changed = true;
      } catch (error) { row.status = 'pending'; row.message = String(error.message || 'Sync failed'); changed = true; }
    }
    if (changed) Storage.replaceLocal('offline_outbox', rows);
  },
  retryOutbox(){const rows=this.all('offline_outbox');rows.forEach(r=>{if(r.status!=='synced')r.status='pending';});Storage.replaceLocal('offline_outbox',rows);this.syncPendingInvoices().then(()=>{Utils.toast('Pending invoices were retried where possible. Other operational records remain queued until their cloud workflow is connected.','info');this.show('data');});}
};
if (typeof window !== 'undefined') window.addEventListener('online', () => { if (typeof Operations !== 'undefined') Operations.syncPendingInvoices(); });
